import React, { useEffect, useState } from 'react';
//import { useParams } from 'react-router-dom';
import { Container, 
  Typography, 
  TextField, 
  CircularProgress,
  Grid,
  Box,
  Button } from '@mui/material';




function ViewProfile() {
  
  const [user, setUser] = useState(null);
  const session = JSON.parse(sessionStorage.getItem('user'));

  const [mobileNumber, setmobileNumber] = useState('');
  const [firstName, setfirstName] = useState('');
  const [lastName, setlastName] = useState('');



  useEffect(() => {
    fetch(`/api/v1/viewUser/${session._id}`)
      .then(response => response.json())
      .then(data => {
        setUser(data.data.user[0]); // Assuming data.data.user is an array with a single user object
      });
  }, [session]);

  if (!user) {
    return (
      <Container style={{ textAlign: 'center', marginTop: '20px' }}>
        <CircularProgress />
      </Container>
    );
  }

  const handleSubmit = async (event) => {
    event.preventDefault();
  
    
  
    //const fundRemain = parsedAvailableFunds - parseFloat(parsedRequestFund);
  
    const formData = new FormData();
    formData.append('userId', session._id);
    formData.append('mobileNumber', mobileNumber);
    //formData.append('requestFund', parsedRequestFund); 
    formData.append('firstName', firstName);
    formData.append('lastName', lastName);
    
  
    try {
      const response = await fetch('/api/v1/loantransaction', {
        method: 'POST',
        body: formData
      });
  
      const result = await response.json();
      if (response.ok) {
        setMessage('Fund request successful!');
        // Clear the form fields
        setAccountNumber('');
        setRequestFund('');
        setImage(null);
        setAgreeToTerms(false);
        setSelectedBank('');
  
        // Reset the file input
        if (fileInputRef.current) {
          fileInputRef.current.value = null;
        }
      } else {
        setMessage(`Failed to request fund: ${result.message}`);
      }
    } catch (error) {
      setMessage(`Error: ${error.message}`);
    }
  };
  

  return (
    <Container>
      <Box sx={{ mt: 5 }}>
      <Typography variant="h4" gutterBottom>
        View User
      </Typography>
      </Box>
      <form onSubmit={handleSubmit}>
        <Grid container spacing={3}>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Username"
              value={user.userName}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Email"
              value={user.email}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Mobile Number"
              value={user.mobileNumber || 'N/A'}
             
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="First Name"
              value={user.personalInfo?.firstName || 'N/A'}
              
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Last Name"
              value={user.personalInfo?.lastName || 'N/A'}
              
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Address"
              value={user.personalInfo?.address || 'N/A'}
              
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Balance"
              value={user.accountInfo?.balance}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Currency"
              value={user.accountInfo?.currency}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Bank Code"
              value={user.accountInfo?.bankcode}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Wallet Address"
              value={user.accountInfo?.walletAddress}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Role"
              value={user.accountRoleInfo?.roleName}
              InputProps={{
                readOnly: true,
              }}
              variant="outlined"
            />
          </Grid>
          
        </Grid>
        <Button
            type="submit"
            variant="contained"
            color="primary"
            sx={{ mt: 2 }}
            >
            Update Profile
          </Button>
      </form>
    </Container>
  );
}

export default ViewProfile;
